export interface CreateAppOptions {
  /** One instance controls admission/readiness throughout server shutdown. */
  lifecycle?: ServerLifecycle;
  /** Overrides the production listener bundle location for isolated route tests. */
  listenerDistPath?: string;
  /** Overrides the Naruto browser bundle location for isolated route tests. */
  narutoDistPath?: string;
  /** Overrides the generated internal engineering guide for isolated route tests. */
  engineeringDistPath?: string;
  /** Overrides generated localization artifacts for isolated route tests. */
  localizationDistPath?: string;
  /** Retains explicit runtime context for existing isolated application callers. */
  environment?: string;
  /** Overrides the MongoDB portfolio store for isolated route tests. */
  portfolioStore?: PortfolioStore;
}

const unsafeMethods = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);
const listenerApplicationPath = '/finitude';
const legacyListenerApplicationPath = '/listen';

/** Identifies shared-content mutations that must authorize before body parsing. */
export const requiresEarlySharedContentAdmin = (method: string, originalUrl: string) => {
  if (!unsafeMethods.has(method.toUpperCase())) return false;
  const pathname = originalUrl.split('?', 1)[0];
  if (pathname === '/feed/post' || pathname.startsWith('/feed/post/')) return true;
  if (!pathname.startsWith('/content/') || pathname.startsWith('/content/me/')) return false;
  return pathname !== '/content/manage' && !pathname.startsWith('/content/manage/');
};

/** Installs an authoritative admin context before JSON, form, or multipart work. */
export const requireSharedContentAdminBeforeBody = (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  if (!requiresEarlySharedContentAdmin(req.method, req.originalUrl)) return next();
  return requireAuth(req, res, () => requireAdmin(req, res, next));
};

/** Resolves only files emitted in Vite's manifest for immutable caching. */
const readListenerManifestAssets = (listenerDistPath: string) => {
  const manifestPath = path.join(listenerDistPath, '.vite', 'manifest.json');
  const assets = new Set<string>();
  try {
    const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8')) as Record<string, unknown>;
    for (const value of Object.values(manifest)) {
      if (!value || typeof value !== 'object' || Array.isArray(value)) continue;
      const chunk = value as { file?: unknown; css?: unknown; assets?: unknown };
      const filenames = [
        ...(typeof chunk.file === 'string' ? [chunk.file] : []),
        ...(Array.isArray(chunk.css) ? chunk.css : []),
        ...(Array.isArray(chunk.assets) ? chunk.assets : [])
      ];
      for (const filename of filenames) {
        if (typeof filename !== 'string') continue;
        const resolved = path.resolve(listenerDistPath, filename.replace(/^\/+/, ''));
        const relative = path.relative(listenerDistPath, resolved);
        if (relative && !relative.startsWith('..') && !path.isAbsolute(relative)) {
          assets.add(resolved);
        }
      }
    }
  } catch {
    // A missing or malformed manifest safely disables long-lived caching.
  }
  return assets;
};

/** Distinguishes missing bundle resources from extensionless listener routes. */
const isListenerAssetRequest = (req: Request) => {
  const listenerPath = req.path.replace(/^\/finitude\/?/, '');
  return listenerPath === 'assets'
    || listenerPath.startsWith('assets/')
    || path.posix.extname(listenerPath) !== '';
};

/** Preserves legacy bookmarks while making `/finitude` the only served SPA prefix. */
const redirectLegacyListener = (req: Request, res: Response) => {
  const suffix = req.originalUrl.slice(legacyListenerApplicationPath.length);
  return res.redirect(308, `${listenerApplicationPath}${suffix}`);
};

/**
 * Account lifecycle pages that moved from the Finitude SPA to Kashewt. The
 * native apps' Create Account button and older links still open the Finitude
 * paths; browsers carry a link token's `#token=` fragment across the redirect.
 */
const kashewtAccountPageRedirects: ReadonlyArray<readonly [string, string]> = [
  ['register', '/account/register'],
  ['register/complete', '/account/register/complete'],
  ['verify-email', '/account/verify-email'],
  ['forgot-password', '/account/forgot-password'],
  ['reset-password', '/account/reset-password']
];

/** Mounts the built listener SPA without allowing its fallback to capture backend routes. */
const mountListenerApplication = (app: Application, listenerDistPath: string) => {
  app.get(legacyListenerApplicationPath, redirectLegacyListener);
  app.get(`${legacyListenerApplicationPath}/*`, redirectLegacyListener);
  for (const [listenerRoute, accountPath] of kashewtAccountPageRedirects) {
    // The query string is dropped: these pages take no parameters, and the token stays in the fragment.
    app.get(`${listenerApplicationPath}/${listenerRoute}`, (_req, res) => res.redirect(303, accountPath));
  }

  const indexPath = path.join(listenerDistPath, 'index.html');
  if (!fs.existsSync(indexPath)) {
    app.use(listenerApplicationPath, (_req, res) => {
      res.setHeader('Cache-Control', 'no-store');
      return res.status(503).json({
        message: 'The Finitude Web listener bundle is unavailable. Build web/dist before starting the listener.'
      });
    });
    return;
  }

  const immutableAssets = readListenerManifestAssets(listenerDistPath);

  app.use(listenerApplicationPath, express.static(listenerDistPath, {
    index: false,
    redirect: false,
    setHeaders: (res, filePath) => {
      if (path.resolve(filePath) === path.resolve(indexPath)) {
        res.setHeader('Cache-Control', 'no-cache');
        return;
      }
      if (immutableAssets.has(path.resolve(filePath))) {
        res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
      }
    }
  }));

  const sendListenerIndex = (_req: Request, res: Response, next: NextFunction) => {
    res.setHeader('Cache-Control', 'no-cache');
    res.sendFile(indexPath, (error) => {
      if (error) next(error);
    });
  };
  app.get(listenerApplicationPath, sendListenerIndex);
  app.get(`${listenerApplicationPath}/*`, (req, res, next) => {
    if (isListenerAssetRequest(req)) {
      res.setHeader('Cache-Control', 'no-store');
      return res.status(404).json({ message: 'The requested listener asset was not found.' });
    }
    return sendListenerIndex(req, res, next);
  });
};

/** Constructs the Express application without connecting to MongoDB or opening a socket. */
export const createApp = (options: CreateAppOptions = {}): Application => {
  const app: Application = express();
  const portfolioStore = options.portfolioStore ?? createMongoPortfolioStore();
  const lifecycle = options.lifecycle ?? new ServerLifecycle();
  const diagnostics = createRequestDiagnostics();
  app.disable('x-powered-by');
  app.set('trust proxy', configuredTrustProxyHops());

  app.use(applySecurityHeaders);
  app.use(diagnostics.observe);
  app.use((req, res, next) => req.path === '/health' ? next() : lifecycle.admit(req, res, next));
  app.use('/assets', express.static(path.join(__dirname, 'public')));

  app.use((_req, res, next) => {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'OPTIONS, GET, POST, PUT, PATCH, DELETE');
    res.setHeader(
      'Access-Control-Allow-Headers',
      'Content-Type, Authorization, Idempotency-Key, If-Match, If-None-Match, X-Finitude-Account-Viewer, X-Finitude-Room-Client'
    );
    res.setHeader(
      'Access-Control-Expose-Headers',
      'Content-Language, ETag, X-Finitude-Account-Viewer, X-Request-Id'
    );
    next();
  });

  // The guide's pages, assets, redirects, and errors all share the admin boundary.
  app.use('/engineering', createEngineeringRouter(options.engineeringDistPath));

  // Cookie mutation proof and shared-content authorization must run before a
  // rejected request can consume application body-parser or upload work.
  app.use(requireSameOriginCookieMutation);
  app.use('/content/manage', requireAuthForWeb, requireAdminForWeb);
  app.use(requireSharedContentAdminBeforeBody);

  // Admin capabilities and import routes authorize before bounded body parsing.
  app.use('/api/admin/v1', createAdminCapabilitiesRouter());
  app.use('/api/admin/v1', createAdminImportRouter());
  app.use('/api/admin/v1', createAdminCatalogReviewRouter());
  app.use('/api/admin/v1', createAdminConversionRouter());
  // Mounted before the catalog router, whose guards apply to every path it receives.
  app.use('/api/admin/v1', createAdminMotionPreviewRouter());
  app.use('/api/admin/v1', createAdminCatalogRouter());

  // Authenticate paid Naruto requests before accepting their bounded JSON bodies.
  app.use('/naruto-mobile/api/v1', narutoMobileRoutes);
  app.use('/naruto/api/v1', createNarutoBrowserRouter());

  // Social authentication and its smaller JSON limit precede the general parser.
  app.use('/api/social/v1', createRoomRouter());
  app.use('/api/social/v1', createSocialRouter());

  // Protect and bound anonymous diagnostics before the general JSON parser can
  // consume a larger request. The listener router owns the final controller.
  app.post(
    '/api/listener/v1/telemetry',
    requireStrictSameOriginBrowserMutation,
    listenerTelemetryRateLimit,
    listenerTelemetryConcurrencyLimit,
    bodyParser.json({ limit: '16kb', strict: true })
  );

  // Parse JSON APIs and browser form submissions before their routers.
  app.use(bodyParser.json());
  app.use(bodyParser.urlencoded({ extended: false }));

  app.use('/admin/projects', createPortfolioAdminRouter({ store: portfolioStore }));
  app.use('/admin', adminRoutes);
  app.use('/auth', authRoutes);
  app.use('/account', createAccountPageRouter());
  app.use('/content', contentRoutes);
  app.use('/feed', feedRoutes);
  app.use('/video', videoRoutes);
  app.use('/api/localizations/v1', createLocalizationRouter(options.localizationDistPath, 'v1'));
  app.use('/api/localizations/v2', createLocalizationRouter(options.localizationDistPath, 'v2'));
  app.use('/api/listener/v1', listenerRoutes);

  const listenerDistPath = options.listenerDistPath
    ?? path.resolve(__dirname, '..', 'web', 'dist');
  mountListenerApplication(app, listenerDistPath);
  mountNarutoBrowserApplication(app, options.narutoDistPath
    ?? path.resolve(__dirname, '..', 'naruto-web', 'dist'));

  app.get('/', attachOptionalAuth, async (req, res, next) => {
    try {
      const projects = await listPublicPortfolioProjects(portfolioStore, (error) => {
        // The homepage stays up with catalog defaults while settings are unreadable.
        console.error(JSON.stringify({
          category: 'portfolio_read_failed',
          errorCategory: safeServerErrorCategory(error),
          requestId: res.locals.requestId,
          occurredAt: new Date().toISOString()
        }));
      });
      return res.status(200).send(renderHomePage({ auth: (req as AuthenticatedRequest).auth, projects }));
    } catch (error) {
      return next(error);
    }
  });

  app.get('/health', createHealthController({
    isDraining: () => lifecycle.draining,
    getRequestMetrics: diagnostics.snapshot
  }));

  app.use(handleApplicationError);

  return app;
};

/** Reports only bounded diagnostics and terminates late failures without Express's raw-error fallback. */
export const handleApplicationError: ErrorRequestHandler = (error, req, res, _next) => {
    if (isCompletedRequestWorkCancellation(req, error)) return;

    const isFileTooLarge = error?.code === 'LIMIT_FILE_SIZE';
    const isTooManyFiles = error?.code === 'LIMIT_FILE_COUNT';
    const isMulterInputError = typeof error?.code === 'string' && error.code.startsWith('LIMIT_');
    const isInvalidJson = error?.type === 'entity.parse.failed';
    const suppliedStatus = isFileTooLarge || isTooManyFiles
      ? 413
      : isMulterInputError || isInvalidJson ? 400 : error?.statusCode;
    const status = Number.isInteger(suppliedStatus) && suppliedStatus >= 400 && suppliedStatus <= 599
      ? suppliedStatus : 500;
    const message: string = isFileTooLarge
      ? error?.field === 'avatar'
        ? `Avatar is too large. The maximum size is ${maxAvatarUploadMb} MB.`
        : error?.field === 'coverArtFile'
          ? `Cover art is too large. The maximum size is ${maxImageUploadMb} MB.`
          : error?.field === 'videoFile'
            ? `Video is too large. The maximum size is ${maxVideoUploadMb} MB.`
          : `Audio file is too large. The maximum size per file is ${maxAudioUploadMb} MB.`
      : isTooManyFiles
        ? 'Too many files were included in this upload.'
        : isMulterInputError
          ? 'Invalid multipart upload.'
          : isInvalidJson
            ? 'Invalid JSON request.'
            : error?.message;
    const data: any = error?.data;

    if (status >= 500) {
      const method = ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS']
        .includes(req.method) ? req.method : 'OTHER';
      const requestArea = req.path === '/api/listener/v1/telemetry'
        ? 'listener_telemetry'
        : req.path.startsWith('/api/listener/v1')
          ? 'listener_api'
          : req.path === listenerApplicationPath || req.path.startsWith(`${listenerApplicationPath}/`)
            ? 'listener_page'
            : req.path.startsWith('/auth')
              ? 'auth'
              : req.path.startsWith('/content')
                ? 'content'
                : req.path.startsWith('/feed')
                  ? 'feed'
                  : req.path.startsWith('/video')
                    ? 'video'
                    : req.path.startsWith('/admin')
                      ? 'admin'
                      : req.path === '/'
                        ? 'root'
                        : 'other';
      console.error(JSON.stringify({
        category: 'server_error',
        errorCategory: safeServerErrorCategory(error),
        requestId: res.locals.requestId,
        requestArea,
        method,
        status,
        occurredAt: new Date().toISOString()
      }));
    }

    if (res.headersSent || res.destroyed || res.writableEnded) {
      res.destroy();
      return;
    }
    if (status >= 500) {
      return res.status(status).json({
        message: 'The service could not complete the request.'
      });
    }
    // Only errors that opt in expose their machine-readable code to clients.
    const exposedCode = error?.exposeCode === true && typeof error?.code === 'string' ? error.code : undefined;
    return res.status(status).json({ message, data, ...(exposedCode ? { code: exposedCode } : {}) });
};

// Keep `tsx src/app.ts` as the runtime entry while imports remain side-effect free.
if (typeof require !== 'undefined' && require.main === module) {
  void import('./server')
    .then(({ startServer }) => startServer())
    .catch(error => {
      console.error(JSON.stringify({
        ...createStartupFailureDiagnostic(error),
        occurredAt: new Date().toISOString()
      }));
      process.exitCode = 1;
    });
}
